import pg from "pg";

export const pool = new pg.Pool({
  connectionString: process.env.DATABASE_URL,
});

// Semua teks dari luar (email, pesan) WAJIB lewat esc() sebelum masuk HTML.
export function esc(value) {
  return String(value).replace(/[&<>"']/g, (c) => ({
    "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;",
  })[c]);
}

export function csrfField(res) {
  return `<input type="hidden" name="_csrf" value="${esc(res.locals.csrf)}">`;
}

export function render(res, title, content, status = 200) {
  const user = res.locals.user;
  const nav = user
    ? `<a href="/akun">Akun</a> ${user.role === "admin" ? '<a href="/admin">Admin</a>' : ""}
       <form method="post" action="/logout">${csrfField(res)}<button>Keluar</button></form>`
    : `<a href="/login">Masuk</a> <a href="/register">Daftar</a>`;
  res.status(status).type("html").send(`<!doctype html>
<html lang="id">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${esc(title)}</title>
</head>
<body>
  <nav><a href="/">Beranda</a> ${nav}</nav>
  <main>
    <h1>${esc(title)}</h1>
    ${content}
  </main>
</body>
</html>`);
}

export function errorBox(message) {
  return message ? `<p role="alert"><strong>${esc(message)}</strong></p>` : "";
}

import { randomBytes, timingSafeEqual } from "node:crypto";

export class HttpError extends Error {
  constructor(status, message) {
    super(message);
    this.status = status;
  }
}

const SAFE = new Set(["GET", "HEAD", "OPTIONS"]);

// Synchronizer token: satu token acak per sesi, ikut di setiap form,
// lalu dicocokkan di setiap request yang mengubah data.
export function csrf(req, res, next) {
  req.session.csrf ??= randomBytes(32).toString("base64url");
  res.locals.csrf = req.session.csrf;
  if (SAFE.has(req.method)) return next();

  const sent = Buffer.from(String(req.body?._csrf ?? ""));
  const expected = Buffer.from(req.session.csrf);
  if (sent.length !== expected.length || !timingSafeEqual(sent, expected)) {
    throw new HttpError(403, "Formulir kedaluwarsa. Muat ulang halaman lalu coba lagi.");
  }
  next();
}

import express from "express";
import session from "express-session";
import connectPgSimple from "connect-pg-simple";
import helmet from "helmet";
import { pool } from "./db.js";
import { csrf } from "./csrf.js";
import { render, esc } from "./views.js";

if (!process.env.SESSION_SECRET) throw new Error("SESSION_SECRET belum diisi");
const production = process.env.NODE_ENV === "production";
const PgStore = connectPgSimple(session);

export const app = express();

app.set("trust proxy", 1); // Render ada di depan aplikasi sebagai proxy HTTPS
app.use(helmet());

// Sebelum session: health check Render tidak perlu membuat baris sesi.
