const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

// Mengembalikan email yang sudah dirapikan, atau null kalau tidak valid.
export function parseEmail(value) {
  if (typeof value !== "string") return null;
  const email = value.trim().toLowerCase();
  return email.length <= 254 && EMAIL.test(email) ? email : null;
}

// Panjang lebih penting daripada aturan "wajib ada simbol".
export function passwordProblem(value) {
  if (typeof value !== "string") return "Kata sandi wajib diisi.";
  if (value.length < 12) return "Kata sandi minimal 12 karakter.";
  if (value.length > 128) return "Kata sandi maksimal 128 karakter.";
  return null;
}

import { Router } from "express";
import argon2 from "argon2";
import { rateLimit } from "express-rate-limit";
import { pool } from "./db.js";
import { HttpError } from "./csrf.js";
import { parseEmail, passwordProblem } from "./validate.js";
import { render, csrfField, errorBox, esc } from "./views.js";

export const auth = Router();

const LOGIN_FAILED = "Email atau kata sandi salah.";
// Hash palsu supaya login dengan email tak terdaftar butuh waktu yang mirip.
const DUMMY_HASH = await argon2.hash("bukan-kata-sandi-siapa-pun");

// Hanya percobaan GAGAL yang dihitung (skipSuccessfulRequests).
// ponytail: penyimpanan di memori, satu instance saja; pakai store bersama (Redis/Postgres) kalau server lebih dari satu.
export const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  limit: 10,
  skipSuccessfulRequests: true,
  standardHeaders: "draft-8",
  legacyHeaders: false,
  handler: (req, res) => {
    res.status(429);
    render(res, "Terlalu banyak percobaan", "<p>Tunggu 15 menit lalu coba lagi.</p>", 429);
  },
});

// Muat pengguna dari database di setiap request, jadi perubahan role
// atau penghapusan akun langsung berlaku.
export async function loadUser(req, res, next) {
  res.locals.user = null;
  if (req.session.userId) {
    const { rows } = await pool.query(
      "SELECT id, email, role FROM users WHERE id = $1",
      [req.session.userId],
    );
    res.locals.user = rows[0] ?? null;
  }
  next();
}

export function requireLogin(req, res, next) {
  if (!res.locals.user) return res.redirect(303, "/login");
  next();
}

// Ganti id sesi saat login supaya id lama (session fixation) tidak berguna.
function startSession(req, userId) {
  return new Promise((resolve, reject) => {
    req.session.regenerate((err) => {
      if (err) return reject(err);
      req.session.userId = userId;
      req.session.save((err2) => (err2 ? reject(err2) : resolve()));
    });
  });
}

function authForm(res, action, button, message, email = "") {
  return `${errorBox(message)}
<form method="post" action="${action}">
  ${csrfField(res)}
  <label>Email <input type="email" name="email" value="${esc(email)}" autocomplete="email" required></label>
  <label>Kata sandi <input type="password" name="password" minlength="12" maxlength="128"
    autocomplete="${action === "/register" ? "new-password" : "current-password"}" required></label>
  <button>${button}</button>
</form>`;
}

auth.get("/register", (req, res) => {
  render(res, "Daftar", authForm(res, "/register", "Daftar"));
});

auth.post("/register", async (req, res) => {
  const email = parseEmail(req.body.email);
  const problem = email ? passwordProblem(req.body.password) : "Email tidak valid.";
  if (problem) {
    return render(res, "Daftar", authForm(res, "/register", "Daftar", problem, req.body.email ?? ""), 422);
  }
  const hash = await argon2.hash(req.body.password); // argon2id, parameter bawaan
  const { rows } = await pool.query(
    `INSERT INTO users (email, password_hash) VALUES ($1, $2)
     ON CONFLICT (email) DO NOTHING RETURNING id`,
    [email, hash],
  );
  if (!rows[0]) {
    return render(res, "Daftar", authForm(res, "/register", "Daftar",
      "Pendaftaran gagal. Kalau sudah punya akun, silakan masuk."), 422);
  }
  await startSession(req, rows[0].id);
  res.redirect(303, "/akun");
});

auth.get("/login", (req, res) => {
  render(res, "Masuk", authForm(res, "/login", "Masuk") +
    '<p><a href="/lupa-sandi">Lupa kata sandi?</a></p>');
});

auth.post("/login", loginLimiter, async (req, res) => {
  const email = parseEmail(req.body.email);
  const password = typeof req.body.password === "string" ? req.body.password : "";
  const { rows } = email
    ? await pool.query("SELECT id, password_hash FROM users WHERE email = $1", [email])
    : { rows: [] };
  const user = rows[0];
  const ok = await argon2.verify(user?.password_hash ?? DUMMY_HASH, password);
  if (!user || !ok) {
    // Pesan sama untuk email salah dan sandi salah: penyerang tidak tahu mana yang terdaftar.
    return render(res, "Masuk", authForm(res, "/login", "Masuk", LOGIN_FAILED), 401);
  }
  await startSession(req, user.id);
  res.redirect(303, "/akun");
});

auth.post("/logout", (req, res, next) => {
  req.session.destroy((err) => {
    if (err) return next(err);
    res.clearCookie("sid");
    res.redirect(303, "/");
  });
});

auth.get("/akun", requireLogin, (req, res) => {
  render(res, "Akun", `<p>Kamu masuk sebagai <strong>${esc(res.locals.user.email)}</strong>
    (role: ${esc(res.locals.user.role)}).</p>`);
});

// Di bagian impor:
import { auth, loadUser } from "./auth.js";

// Tepat di bawah app.use(csrf):
app.use(loadUser);

// Setelah rute "/" dan sebelum penangan 404:
app.use(auth);

// Tambahkan di bawah requireLogin:
export function requireRole(role) {
  return (req, res, next) => {
    if (!res.locals.user) return res.redirect(303, "/login");
    if (res.locals.user.role !== role) throw new HttpError(403, "Kamu tidak punya akses ke halaman ini.");
    next();
  };
}

// Tambahkan di bagian paling bawah berkas:
auth.get("/admin", requireRole("admin"), async (req, res) => {
  const { rows } = await pool.query(
    "SELECT email, role, created_at FROM users ORDER BY created_at DESC LIMIT 100",
  );
  const items = rows.map((u) => `<li>${esc(u.email)} (${esc(u.role)})</li>`).join("");
  render(res, "Admin", `<p>${rows.length} pengguna terbaru:</p><ul>${items}</ul>`);
});

