import { Router } from "express";
import { createHash, randomBytes } from "node:crypto";
import argon2 from "argon2";
import { pool } from "./db.js";
import { rateLimit } from "express-rate-limit";
import { parseEmail, passwordProblem } from "./validate.js";
import { render, csrfField, errorBox, esc } from "./views.js";

export const reset = Router();

const TTL_MINUTES = 30;
const sha256 = (s) => createHash("sha256").update(s).digest("hex");

// Token acak 256 bit dikirim ke pengguna; database hanya menyimpan hash-nya.
export async function createResetToken(userId) {
  const token = randomBytes(32).toString("base64url");
  await pool.query("DELETE FROM password_resets WHERE user_id = $1", [userId]);
  await pool.query(
    `INSERT INTO password_resets (token_hash, user_id, expires_at)
     VALUES ($1, $2, now() + make_interval(mins => $3))`,
    [sha256(token), userId, TTL_MINUTES],
  );
  return token;
}

// ponytail: tautan dicetak di log server; ganti dengan layanan email (Resend, Postmark, SES) sebelum dipakai sungguhan.
function sendResetEmail(email, link) {
  console.log(`[email ke ${email}] Atur ulang kata sandi: ${link}`);
}

// Jawaban /lupa-sandi selalu 200, jadi semua request dihitung.
const forgotLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  limit: 5,
  standardHeaders: "draft-8",
  legacyHeaders: false,
});

const SENT = "Kalau email itu terdaftar, tautan atur ulang sudah dikirim. Tautan berlaku 30 menit.";

reset.get("/lupa-sandi", (req, res) => {
  render(res, "Lupa kata sandi", `<form method="post" action="/lupa-sandi">
  ${csrfField(res)}
  <label>Email <input type="email" name="email" autocomplete="email" required></label>
  <button>Kirim tautan</button>
</form>`);
});

reset.post("/lupa-sandi", forgotLimiter, async (req, res) => {
  const email = parseEmail(req.body.email);
  if (email) {
    const { rows } = await pool.query("SELECT id FROM users WHERE email = $1", [email]);
    if (rows[0]) {
      const token = await createResetToken(rows[0].id);
      const base = process.env.APP_URL ?? `http://localhost:${process.env.PORT || 3000}`;
      sendResetEmail(email, `${base}/atur-ulang?token=${token}`);
    }
  }
  // Jawaban sama persis, terdaftar atau tidak.
  render(res, "Cek email kamu", `<p>${SENT}</p>`);
});

function resetForm(res, token, message) {
  return `${errorBox(message)}
<form method="post" action="/atur-ulang">
  ${csrfField(res)}
  <input type="hidden" name="token" value="${esc(token)}">
  <label>Kata sandi baru <input type="password" name="password" minlength="12" maxlength="128"
    autocomplete="new-password" required></label>
  <button>Simpan</button>
</form>`;
}

reset.get("/atur-ulang", (req, res) => {
  render(res, "Atur ulang kata sandi", resetForm(res, String(req.query.token ?? "")));
});

reset.post("/atur-ulang", async (req, res) => {
  const token = String(req.body.token ?? "");
  const problem = passwordProblem(req.body.password);
  if (problem) return render(res, "Atur ulang kata sandi", resetForm(res, token, problem), 422);

  // DELETE ... RETURNING: token langsung hangus begitu dipakai, sekali saja.
  const { rows } = await pool.query(
    `DELETE FROM password_resets
     WHERE token_hash = $1 AND expires_at > now()
     RETURNING user_id`,
    [sha256(token)],
  );
  if (!rows[0]) {
    return render(res, "Atur ulang kata sandi",
      errorBox("Tautan tidak valid atau sudah kedaluwarsa. Minta tautan baru."), 400);
  }
  const userId = rows[0].user_id;
  await pool.query("UPDATE users SET password_hash = $1 WHERE id = $2",
    [await argon2.hash(req.body.password), userId]);
  // Keluarkan semua sesi lama pengguna ini, termasuk milik penyerang kalau ada.
  await pool.query(`DELETE FROM "session" WHERE (sess->>'userId')::bigint = $1`, [userId]);
  render(res, "Kata sandi diganti", '<p>Silakan <a href="/login">masuk</a> dengan kata sandi baru.</p>');
});

import express from "express";
