const production = process.env.NODE_ENV === "production";
const PgStore = connectPgSimple(session);

export const app = express();

app.set("trust proxy", 1); // Render ada di depan aplikasi sebagai proxy HTTPS
app.use(helmet());

// Sebelum session: health check Render tidak perlu membuat baris sesi.
app.get("/health", async (req, res) => {
