import { test, after } from "node:test";
import assert from "node:assert/strict";
import { randomUUID } from "node:crypto";
import request from "supertest";
import { app } from "../src/app.js";
import { pool } from "../src/db.js";
import { createResetToken } from "../src/reset.js";

const PASS = "kuda-makan-nasi-goreng";
const newEmail = () => `t-${randomUUID()}@contoh.test`;

after(async () => {
  await pool.query("DELETE FROM users WHERE email LIKE '%@contoh.test'");
  await pool.end();
});

// Ambil token CSRF dari form di halaman, seperti yang dilakukan browser.
async function csrfFrom(agent, path) {
  const res = await agent.get(path);
  return res.text.match(/name="_csrf" value="([^"]+)"/)[1];
}

async function register(agent, email, password = PASS) {
  const _csrf = await csrfFrom(agent, "/register");
  return agent.post("/register").type("form").send({ _csrf, email, password });
}

async function login(agent, email, password = PASS) {
  const _csrf = await csrfFrom(agent, "/login");
  return agent.post("/login").type("form").send({ _csrf, email, password });
}

test("header keamanan dan cookie sesi yang aman", async () => {
  const res = await request(app).get("/login");
  assert.match(res.headers["content-security-policy"], /default-src 'self'/);
  assert.equal(res.headers["x-content-type-options"], "nosniff");
  const cookie = res.headers["set-cookie"][0];
  assert.match(cookie, /^sid=/);
  assert.match(cookie, /HttpOnly/);
  assert.match(cookie, /SameSite=Lax/);
});

test("daftar, sandi tersimpan sebagai hash argon2id, lalu bisa buka akun", async () => {
  const agent = request.agent(app);
  const email = newEmail();
  const res = await register(agent, email);
  assert.equal(res.status, 303);
  assert.equal(res.headers.location, "/akun");

  const { rows } = await pool.query("SELECT password_hash FROM users WHERE email = $1", [email]);
  assert.match(rows[0].password_hash, /^\$argon2id\$/);

  const akun = await agent.get("/akun");
  assert.equal(akun.status, 200);
  assert.match(akun.text, new RegExp(email));
});

test("validasi: sandi pendek dan email rusak ditolak", async () => {
  const agent = request.agent(app);
  assert.equal((await register(agent, newEmail(), "pendek")).status, 422);
  assert.equal((await register(agent, "bukan-email")).status, 422);
});

test("POST tanpa token CSRF ditolak 403", async () => {
  const agent = request.agent(app);
  await agent.get("/login");
  const res = await agent.post("/login").type("form").send({ email: "a@contoh.test", password: PASS });
  assert.equal(res.status, 403);
});

test("pesan gagal login sama untuk email tak dikenal dan sandi salah", async () => {
  const agent = request.agent(app);
  const email = newEmail();
  await register(agent, email);
  const salahSandi = await login(request.agent(app), email, "sandi-yang-salah-sekali");
  const takDikenal = await login(request.agent(app), newEmail());
  assert.equal(salahSandi.status, 401);
  assert.equal(takDikenal.status, 401);
  assert.match(salahSandi.text, /Email atau kata sandi salah/);
  assert.match(takDikenal.text, /Email atau kata sandi salah/);
});

test("login mengganti id sesi, logout menghapus sesi", async () => {
  const email = newEmail();
  await register(request.agent(app), email);

  const agent = request.agent(app);
  const before = (await agent.get("/login")).headers["set-cookie"][0].split(";")[0];
  const res = await login(agent, email);
  assert.equal(res.status, 303);
  const afterLogin = res.headers["set-cookie"][0].split(";")[0];
  assert.notEqual(before, afterLogin);

  const _csrf = await csrfFrom(agent, "/akun");
  assert.equal((await agent.post("/logout").type("form").send({ _csrf })).status, 303);
  const akun = await agent.get("/akun");
  assert.equal(akun.status, 303);
  assert.equal(akun.headers.location, "/login");
});

test("route admin: tamu dialihkan, user 403, admin 200", async () => {
  assert.equal((await request(app).get("/admin")).status, 303);

  const agent = request.agent(app);
  const email = newEmail();
  await register(agent, email);
  assert.equal((await agent.get("/admin")).status, 403);

  await pool.query("UPDATE users SET role = 'admin' WHERE email = $1", [email]);
  assert.equal((await agent.get("/admin")).status, 200);
});

test("atur ulang sandi: token sekali pakai, sesi lama hangus", async () => {
  const lama = request.agent(app);
  const email = newEmail();
  await register(lama, email);
  const { rows } = await pool.query("SELECT id FROM users WHERE email = $1", [email]);

  const token = await createResetToken(rows[0].id);
  const stored = await pool.query("SELECT token_hash FROM password_resets WHERE user_id = $1", [rows[0].id]);
  assert.notEqual(stored.rows[0].token_hash, token); // yang disimpan hanya hash

  const agent = request.agent(app);
  const _csrf = await csrfFrom(agent, `/atur-ulang?token=${token}`);
  const baru = "sandi-baru-yang-panjang";
  const ok = await agent.post("/atur-ulang").type("form").send({ _csrf, token, password: baru });
  assert.equal(ok.status, 200);

  const lagi = await agent.post("/atur-ulang").type("form").send({ _csrf, token, password: baru });
  assert.equal(lagi.status, 400);

  assert.equal((await lama.get("/akun")).status, 303); // sesi lama sudah dihapus
  assert.equal((await login(request.agent(app), email, baru)).status, 303);
});

test("atur ulang sandi: token kedaluwarsa ditolak", async () => {
  const email = newEmail();
  await register(request.agent(app), email);
  const { rows } = await pool.query("SELECT id FROM users WHERE email = $1", [email]);
  const token = await createResetToken(rows[0].id);
  await pool.query(
    "UPDATE password_resets SET expires_at = now() - interval '1 minute' WHERE user_id = $1",
    [rows[0].id],
  );
  const agent = request.agent(app);
  const _csrf = await csrfFrom(agent, `/atur-ulang?token=${token}`);
  const res = await agent.post("/atur-ulang").type("form").send({ _csrf, token, password: PASS });
  assert.equal(res.status, 400);
});

// Taruh paling akhir: limiter di memori ikut menghitung kegagalan dari tes lain.
test("login dibatasi setelah terlalu banyak kegagalan", async () => {
  const statuses = [];
  for (let i = 0; i < 11; i++) {
    statuses.push((await login(request.agent(app), newEmail(), "sandi-yang-salah-sekali")).status);
  }
  assert.equal(statuses.at(-1), 429);
});
